def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    prev_bids = []
    aggressive_count = 0
    weak_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 120:
            rich_count += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            aggressive_count += 1
        if opp.get('budget', 0) < 40 or opp.get('hp', 0) <= 1:
            weak_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                b = float(prev.get('bid', 0))
                if b >= 0:
                    prev_bids.append(b)
                    if b >= 90:
                        aggressive_count += 1
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 2 or no_water_days >= 1
    semi_urgent = hp <= 4

    if urgent:
        target = max(92.0, highest_prev + 2.0, 110.0 * scarcity + 20.0)
    elif supply >= 23:
        target = 18.0 + 6.0 * scarcity
    elif supply >= 21:
        target = 28.0 + 10.0 * scarcity
    elif supply >= 19:
        target = max(38.0, avg_prev * 0.48, highest_prev * 0.42)
    elif supply >= 17:
        target = max(52.0, avg_prev * 0.62, highest_prev * 0.68)
    else:
        target = max(72.0, avg_prev * 0.78, highest_prev + 1.5)

    if aggressive_count >= 2 and supply <= 18 and not urgent:
        target += 8.0
    if rich_count >= 2 and supply <= 17:
        target += 6.0
    if weak_count >= 2 and hp > 3 and supply >= 20:
        target -= 8.0
    if semi_urgent and supply <= 18:
        target += 10.0
    if day >= 8 and hp > 5:
        target -= 6.0
    if day >= 8 and urgent:
        target += 8.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 20.0 * (8 - day)
    max_affordable = budget - reserve_floor
    if urgent:
        max_affordable = budget
    if max_affordable < 0:
        max_affordable = min(budget, DAILY_SALARY * 0.35)

    bid = min(budget, max_affordable, target)

    if urgent and bid < min(budget, 85.0):
        bid = min(budget, 85.0)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        # If no opponents, spend enough to cover our requirement.
        return min(budget, DAILY_SALARY * 0.35)

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
        if prev and prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If someone was bidding extremely high yesterday, we assume strong competition.
    extreme_competition = highest_prev_bid >= (DAILY_SALARY * 0.85)

    # If we are already in danger (low hp / many no-water days), increase urgency.
    urgent = (hp <= 2.5) or (no_water_days >= 2)

    # Base bid scales with supply: lower supply increases competitive need.
    # Map supply in [15,25] to a multiplier in [1.05, 0.85]
    if MAX_SUPPLY != MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_multiplier = 1.05 - 0.20 * supply_norm  # 15->1.05, 25->0.85

    # Strategy:
    # - If extreme competition: bid enough to avoid losing, but not full send unless we are urgent.
    # - If not extreme: bid moderately and conserve budget.
    if extreme_competition:
        if urgent:
            target = DAILY_SALARY * 0.95
        else:
            target = max(highest_prev_bid * 0.55, DAILY_SALARY * 0.45)
    else:
        if urgent:
            target = DAILY_SALARY * 0.75
        else:
            # Slightly undercut expected winner pressure.
            target = max(DAILY_SALARY * 0.40, highest_prev_bid * 0.35)

    target *= supply_multiplier

    # Cap by budget and ensure non-negative
    if budget <= 0:
        return 0.0
    bid = min(budget, max(0.0, target))

    # Additional safeguard: if our hp is very low, go aggressive near end of episode.
    if day >= 8 and hp <= 3.0:
        bid = min(budget, max(bid, DAILY_SALARY * 0.85))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    num_active_players = num_alive_opponents + 1 

    base_bid = DAILY_SALARY * 0.65 

    if my_status['hp'] <= 2: 
        base_bid = DAILY_SALARY * 0.95
    elif my_status['no_water_days'] >= 1: 
        base_bid = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 4: 
        base_bid = DAILY_SALARY * 0.75

    available_water_units = int(day_context['supply'] / WATER_REQ)

    if available_water_units < num_active_players: 
        if my_status['hp'] <= 3: 
            base_bid = DAILY_SALARY * 0.98
        else: 
            base_bid = max(base_bid, DAILY_SALARY * 0.8) 
            base_bid *= 1.1 
    elif available_water_units >= num_active_players + 1: 
        if my_status['hp'] > 5: 
            base_bid *= 0.7
        else: 
            base_bid *= 0.85

    highest_prev_bid = 0.0
    for agent_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                highest_prev_bid = max(highest_prev_bid, prev['bid'])

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8: 
            if my_status['hp'] <= 3: 
                base_bid = max(base_bid, highest_prev_bid + 10)
            else: 
                base_bid = max(base_bid, highest_prev_bid + 2)
        elif highest_prev_bid >= DAILY_SALARY * 0.5: 
            if my_status['hp'] <= 5: 
                base_bid = max(base_bid, highest_prev_bid + 1)
            else: 
                base_bid = max(base_bid, highest_prev_bid * 1.05)
    else: 
        if day_context['day'] <= 2 and my_status['hp'] > 5:
            base_bid = min(base_bid, DAILY_SALARY * 0.55)
        elif my_status['hp'] <= 3: 
            base_bid = DAILY_SALARY * 0.9

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2: 
        if my_status['hp'] <= 5: 
            base_bid = max(base_bid, DAILY_SALARY * 0.98)
        elif my_status['budget'] > DAILY_SALARY * 2 and my_status['hp'] < 10: 
            base_bid = max(base_bid, DAILY_SALARY * 0.9)

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(1.0, final_bid)

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        target = max(avg_opp_bid * 1.1, 75.0)
    elif day_context['supply'] < 18:
        target = avg_opp_bid * 0.95
    else:
        target = min(avg_opp_bid * 0.7, 40.0)

    return float(min(my_status['budget'], max(5.0, target)))
